export const dispose = <T extends any[]>(
  ...derivedSignalsOrEffects: { [K in keyof T]: DerivedSignal<T[K]> | Effect }
): void => {
  derivedSignalsOrEffects.forEach((derSigOrEff) => derSigOrEff.dispose());
};

