export const getGenericMethods = <InputSignal extends InputSignalType, T>(
  // generic methods are valid even for null or undefined
  baseSignal: MaybeSignal<T>,
): GenericMethods<InputSignal, T> => {
  const isLiveSignal = valueIsLiveSignal(baseSignal);
  const valueGetter = () => value(baseSignal) as Primitive;
  const lengthGetter = () => {
    const val = value(baseSignal);
    if (typeof val === "string" || Array.isArray(val)) return val.length;
    return NaN;
  };

  return {
    or: <A>(
      alternativeValue: MaybeSignal<A>,
    ): DeriverReturnType<
      InputSignal,
      NonNullable<Extract<T, Primitive>> | A
    > => {
      const deriver = () => {
        const altValue = value(alternativeValue);
        return value(baseSignal) || altValue;
      };

      return (
        isLiveSignal ? derive(deriver) : deadSignal(deriver())
      ) as DeriverReturnType<
        InputSignal,
        NonNullable<Extract<T, Primitive>> | A
      >;
    },
    is: {
      ...getComparisonMethods(isLiveSignal, valueGetter, false),
      ...getLengthMethods(isLiveSignal, lengthGetter, false),
    },
    if: {
      ...getComparisonMethods(isLiveSignal, valueGetter, true),
      ...getLengthMethods(isLiveSignal, lengthGetter, true),
    },
  } as unknown as GenericMethods<InputSignal, T>;
};

export const getMutatingAndNonMutatingDataMethods = <
  InputSignal extends InputSignalType,
  T,
>(
  baseSignal: BaseSignal<T>,
  nonNullableInitialValue?: NonNullable<T extends Record<string, any> ? {} : T>,
): MutatingAndNonMutatingMethods<InputSignal, T> => {
  const nonNullInitialValue =
    nonNullableInitialValue === undefined
      ? baseSignal.nonReactiveValue
      : nonNullableInitialValue;

  // ARRAY CHECK MUST BE BEFORE OBJECT CHECK
  if (Array.isArray(nonNullInitialValue)) {
    return getArrayMutatingAndNonMutatingMethods<
      InputSignal,
      Extract<T, any[]>
    >(
      baseSignal as any,
    ) as MutatingAndNonMutatingMethods<InputSignal, T>;
  }

  if (isPlainObject(nonNullInitialValue)) {
    return getObjectMutatingAndNonMutatingMethods<
      InputSignal,
      Extract<T, Record<string, any>>
    >(
      baseSignal as any,
    ) as MutatingAndNonMutatingMethods<InputSignal, T>;
  }

  if (typeof nonNullInitialValue === "string") {
    return getStringSignalMethods<InputSignal>(
      baseSignal as any,
    ) as MutatingAndNonMutatingMethods<InputSignal, T>;
  }

  if (typeof nonNullInitialValue === "number") {
    return getNumberSignalMethods<InputSignal>(
      baseSignal as any,
    ) as MutatingAndNonMutatingMethods<InputSignal, T>;
  }

  if (typeof nonNullInitialValue === "boolean") {
    return getBooleanSignalMethods(
      baseSignal as any,
    ) as MutatingAndNonMutatingMethods<InputSignal, T>;
  }

  return {} as MutatingAndNonMutatingMethods<InputSignal, T>;
};

examples:
